function page = report_header(titleText)
    % REPORT_HEADER Shared high-contrast, offline HTML theme for every report.
    % Input: page title. Output: UTF-8 HTML prefix, styles and chart-size controls.

    page = ['<!doctype html><html lang="en"><head><meta charset="utf-8">' ...
            '<meta name="viewport" content="width=device-width,initial-scale=1">' ...
            '<title>' titleText '</title><style>' ...
            ':root{color-scheme:light;--ink:#111827;--muted:#334155;--line:#cbd5e1;--blue:#064e91}' ...
            '*{box-sizing:border-box}body{margin:0;background:#f1f5f9;color:var(--ink);font:18px/1.6 Arial,Helvetica,sans-serif}' ...
            'main{max-width:1640px;margin:auto;padding:28px}h1{font-size:34px;line-height:1.2;margin:0 0 18px;font-weight:800}' ...
            'h2{font-size:25px;margin:30px 0 12px;font-weight:750}h3{font-size:21px;font-weight:700}' ...
            'p{margin:10px 0}a{color:var(--blue);font-weight:650;text-underline-offset:3px}' ...
            '.card,.chart-card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin:18px 0;box-shadow:0 2px 7px #0f172a0a}' ...
            '.kpis{display:flex;gap:14px;flex-wrap:wrap}.kpi{flex:1;min-width:220px;background:#fff;border:1px solid var(--line);border-radius:10px;padding:18px}' ...
            '.kpi strong{display:block;font-size:28px;font-weight:800;color:#0f172a}.muted{color:var(--muted)}' ...
            '.table-scroll{overflow:auto;border:1px solid var(--line);border-radius:8px;margin:14px 0}' ...
            'table{border-collapse:collapse;width:100%;font-size:17px;background:#fff}th,td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}' ...
            'th{background:#dce8f5;color:#0f172a;font-weight:800;position:sticky;top:0}tbody tr:nth-child(even){background:#f5f8fc}' ...
            'td.num{font-variant-numeric:tabular-nums;text-align:right}.pass{color:#14532d;font-weight:800}.fail{color:#991b1b;font-weight:800}' ...
            '.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0}' ...
            'button,.button{background:#0b4f8a;color:#fff;border:1px solid #083c69;border-radius:7px;padding:9px 14px;font:700 16px Arial,Helvetica,sans-serif;cursor:pointer;text-decoration:none}' ...
            '.button.secondary,button.secondary{background:#fff;color:#0f172a;border-color:#64748b}' ...
            '.chart-shell{overflow:auto;background:#fff;border:1px solid #94a3b8;padding:8px;border-radius:6px}' ...
            '.chart-shell img{display:block;width:var(--chart-width,2200px);max-width:none;height:auto;background:#fff}' ...
            '.fit-chart .chart-shell img{width:100%;max-width:100%}.help{font-size:16px;color:#334155;margin:8px 0}' ...
            'input{font:18px Arial,Helvetica,sans-serif;padding:11px 13px;border:1px solid #64748b;border-radius:7px;min-width:320px}' ...
            'code{background:#e7eef7;padding:3px 6px;border-radius:4px;color:#0f172a}footer{font-size:15px;color:#334155;margin:30px 0}' ...
            '@media(max-width:700px){main{padding:14px}h1{font-size:28px}.card,.chart-card{padding:14px}table{font-size:16px}}' ...
            '@media print{body{background:#fff}main{max-width:none}.toolbar,button{display:none}.chart-shell{overflow:visible}.chart-shell img{width:100%;max-width:100%}}' ...
            '</style><script>' ...
            'function setChartMode(button,fit){button.closest(".chart-card").classList.toggle("fit-chart",fit)}' ...
            'function filterRows(input){const q=input.value.toLowerCase();for(const r of document.querySelectorAll("tbody[data-filter] tr")){r.hidden=!r.textContent.toLowerCase().includes(q)}}' ...
            '</script></head><body><main>'];
end
